import type { Item } from '../../types/index.js'
import { collapsedTextOf } from '../page/collapsed-text-of.js'

/**
 * The copy-for-Claude text: the template with `{title}`, `{url}` and `{source}` filled once each, the item's fields made one line first, since feed text is untrusted.
 *
 * @param template the user's template
 * @param item the item
 * @param sourceName the name of the item's source
 */
export function copyTextOf(template: string, item: Item, sourceName: string): string {
  const values = new Map([
    ['{title}', item.title],
    ['{url}', item.url],
    ['{source}', sourceName],
  ])

  // One pass, so a title that holds a placeholder is not filled again.
  return template.replace(/\{(?:title|url|source)\}/g, placeholder =>
    collapsedTextOf(values.get(placeholder) ?? '').trim(),
  )
}

files.hooks/actions/copy-with-tool.ts:
import type { Host } from '../host/host.js'
import { messageOf } from '../refresh/message-of.js'
import { clipboardArgvsOf } from './clipboard-argvs-of.js'
import { platformOf } from './platform-of.js'

/**
 * Copies text with the platform's clipboard tools, trying each in order until one exits cleanly; never throws.
 *
 * @param host the engine
 * @param text what to copy
 * @returns undefined once copied, else why the last tool failed
 */
export async function copyWithTool(host: Host, text: string): Promise<string | undefined> {
  let reason = 'no clipboard tool'

  for (const argv of clipboardArgvsOf(await platformOf(host))) {
    try {
      const { exitCode, stderr } = await host.processRun(argv, { stdin: text, timeoutMs: 5000 })

      if (exitCode === 0) {
        return undefined
      }

      reason = `${argv[0]} exited with ${exitCode}${stderr.trim() === '' ? '' : `: ${messageOf(stderr)}`}`
    } catch (error) {
      reason = `${argv[0]}: ${messageOf(error)}`
    }

    host.debug(`herald: clipboard: ${reason}`)
  }

  return reason
}

files.hooks/actions/deps-copy-text-of.ts:
import type { StackItem } from '../../types/index.js'
import { collapsedTextOf } from '../page/collapsed-text-of.js'

/**
 * The copy-for-Claude text of a stack item: the deps template with `{pkg}`, `{current}`, `{new}` and `{url}` filled once each (an unknown version as `unknown`), every value made one line first, since feed text is untrusted.
 *
 * @param template the user's deps template
 * @param item the stack item
 */
export function depsCopyTextOf(template: string, item: StackItem): string {
  const values = new Map([
    ['{pkg}', item.release.name],
    ['{current}', item.release.current ?? 'unknown'],
    ['{new}', item.release.version ?? item.title],
    ['{url}', item.url],
  ])

  // One pass, so a value that holds a placeholder is not filled again.
  return template.replace(/\{(?:pkg|current|new|url)\}/g, placeholder =>
    collapsedTextOf(values.get(placeholder) ?? '').trim(),
  )
}

